    /*
     * 壁纸主色提取：每 4 秒从背景视频抽一帧，取「饱和像素」的加权平均，得到 UI 高亮色。
     * 只写 `--aem-accent` / `--aem-accent-soft`，样式层的呼吸光与描边都读这两个变量。
     */
    function mountAccent() {
      if (typeof document === 'undefined') return function () {};
      const canvas = document.createElement('canvas');
      canvas.width = 28;
      canvas.height = 16;
      const probe = canvas.getContext ? canvas.getContext('2d', { willReadFrequently: true }) : null;
      let timer = 0;

      function paint() {
        const video = document.querySelector('#aem-backdrop video');
        if (!probe || !video || video.readyState < 2 || !video.videoWidth) return;
        try {
          probe.drawImage(video, 0, 0, canvas.width, canvas.height);
          const data = probe.getImageData(0, 0, canvas.width, canvas.height).data;
          let r = 0, g = 0, b = 0, weight = 0;
          for (let i = 0; i < data.length; i += 4) {
            const red = data[i], green = data[i + 1], blue = data[i + 2];
            const max = Math.max(red, green, blue);
            const min = Math.min(red, green, blue);
            const sat = max === 0 ? 0 : (max - min) / max;
            /* 近灰的壁纸底色不参与取色，否则高亮会永远偏灰白。 */
            const w = sat < 0.16 ? 0 : 0.3 + sat * (0.2 + (max / 255) * 0.5);
            if (w === 0) continue;
            r += red * w; g += green * w; b += blue * w; weight += w;
          }
          if (weight === 0) return;
          r /= weight; g /= weight; b /= weight;
          const max = Math.max(r, g, b) || 1;
          const lift = Math.min(1.85, 232 / max);
          r = Math.min(255, r * lift); g = Math.min(255, g * lift); b = Math.min(255, b * lift);
          const rgb = 'rgb(' + Math.round(r) + ',' + Math.round(g) + ',' + Math.round(b) + ')';
          const soft = 'rgba(' + Math.round(r) + ',' + Math.round(g) + ',' + Math.round(b) + ',.42)';
          let lr = 0, ln = 0;
          for (let yy = 0; yy < 16; yy += 1) {
            for (let xx = 0; xx < 6; xx += 1) {
              const ii = (yy * 28 + xx) * 4;
              lr += 0.2126 * data[ii] + 0.7152 * data[ii + 1] + 0.0722 * data[ii + 2];
              ln += 1;
            }
          }
          const leftLuma = ln ? lr / ln / 255 : 0.6;
          document.documentElement.classList.toggle('mw-luma-dark', leftLuma < 0.68);
          const root = document.documentElement;
          root.style.setProperty('--aem-accent', rgb);
          root.style.setProperty('--aem-accent-soft', soft);
        } catch (error) {
          /* 视频还没解码出帧时 drawImage 会抛错；下一轮再取。 */
        }
      }

      timer = setInterval(paint, 4200);
      const kick = setTimeout(paint, 1200);
      return function () {
        clearInterval(timer);
        clearTimeout(kick);
      };
    }

    /* 禅模式：Ctrl/⌘+Shift+Z 淡出侧栏与标题栏，只留下壁纸和对话。 */
    function mountZenMode() {
      if (typeof document === 'undefined') return function () {};
      function onKey(event) {
        if (event.defaultPrevented) return;
        const key = event.key ? String(event.key).toLowerCase() : '';
        if (!((event.ctrlKey || event.metaKey) && event.shiftKey && key === 'z')) return;
        event.preventDefault();
        document.documentElement.classList.toggle('aem-zen');
      }
      window.addEventListener('keydown', onKey, true);
      return function () {
        window.removeEventListener('keydown', onKey, true);
        document.documentElement.classList.remove('aem-zen');
      };
    }

