      '.AnXs9G_options [class*="_switch_"] [class*="_thumb_"],',
      '.aem-panel-skin [class*="_switch_"] [class*="_thumb_"]{background:#3f9c35 !important;',
      '  box-shadow:0 1px 1px rgba(0,0,0,.35) !important}',
      '.aem-set-hint{font-size:12px;color:var(--dsw-alias-label-secondary)}',
